import SwiftUI
struct ResumePreviewView: View { @EnvironmentObject private var appState: AppState; var body: some View { ScrollView { GeometryReader { geo in let width = geo.size.width - 32; resumePage(width:width) }.frame(height:UIScreen.main.bounds.width*1.414+64) }.background(DS.ColorToken.background) }
    private func resumePage(width:CGFloat)->some View { VStack(alignment:.leading,spacing:12){ Text(appState.activeResume.name).font(.system(size:26,weight:.bold)).foregroundStyle(templateAccent); ForEach(appState.activeResume.sections.filter{$0.isVisible}.sorted(by:{$0.order<$1.order})){section in VStack(alignment:.leading,spacing:5){Text(section.title.uppercased()).font(.system(size:10,weight:.bold)).foregroundStyle(templateAccent); Divider(); ForEach(section.fields){field in HStack(alignment:.firstTextBaseline){Text(field.label).font(.system(size:9,weight:.semibold)).frame(width:80,alignment:.leading); Text(field.value).font(.system(size:9,weight:field.isBold ? .semibold : .regular)).fixedSize(horizontal:false,vertical:true)}}}}; Spacer() }.padding(28).frame(width:width,height:width*1.414,alignment:.topLeading).background(Color.white).foregroundStyle(Color.black).shadow(color:.black.opacity(0.12),radius:12,y:8).padding(.horizontal,16).padding(.vertical,24) }
    private var templateAccent: Color { ResumeTemplate.all.first(where:{$0.id==appState.selectedTemplateID})?.accent ?? DS.ColorToken.primary }
}
